ON CONFLICT (slug, version) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  long_description = EXCLUDED.long_description,
  category = EXCLUDED.category,
  report_type = EXCLUDED.report_type,
  tier = EXCLUDED.tier,
  industry = EXCLUDED.industry,
  tags = EXCLUDED.tags,
  style = EXCLUDED.style,
  orientation = EXCLUDED.orientation,
  page_count = EXCLUDED.page_count,
  schema = EXCLUDED.schema,
  access_tier = EXCLUDED.access_tier,
  supported_modules = EXCLUDED.supported_modules,
  required_bindings = EXCLUDED.required_bindings,
  brand_safe = EXCLUDED.brand_safe,
  production_ready = EXCLUDED.production_ready,
  compatibility_version = EXCLUDED.compatibility_version,
  preview_schema = EXCLUDED.preview_schema,
  updated_at = now();

-- Publish them. Done as a separate statement so a re-run republishes anything
-- an operator archived without resurrecting their own entries.
UPDATE public.template_library_entries
SET status = 'published',
    published_at = COALESCE(published_at, now())
WHERE version = 1
  AND status = 'draft'
  AND slug IN ($tlt$investor-compass$tlt$, $tlt$executive-brief$tlt$, $tlt$property-snapshot$tlt$, $tlt$due-diligence-dossier$tlt$, $tlt$suburb-market-compass$tlt$, $tlt$suburb-snapshot$tlt$, $tlt$postcode-market-analysis$tlt$, $tlt$statewide-market-review$tlt$, $tlt$property-comparison-matrix$tlt$, $tlt$ten-year-cash-flow-projection$tlt$, $tlt$client-fact-find$tlt$, $tlt$compliance-file-review$tlt$);
